<?php
require_once dirname(__DIR__).'/includes/functions.php';require_role('counselor');$status=$_GET['status']??'';$sql="SELECT a.*,j.title job_title,j.company,u.name student_name,u.education_level FROM job_applications a JOIN job_opportunities j ON j.id=a.job_id JOIN users u ON u.id=a.user_id";$params=[];$types='';if(in_array($status,['submitted','under_review','shortlisted','unsuccessful','accepted'],true)){$sql.=' WHERE a.status=?';$params[]=$status;$types='s';}$sql.=' ORDER BY a.applied_at DESC';$stmt=$con->prepare($sql);if($params)$stmt->bind_param($types,...$params);$stmt->execute();$apps=$stmt->get_result();$pageTitle='Application reviews';require dirname(__DIR__).'/includes/header.php';?>
<div class="container py-5"><div class="mb-4"><h1>Application reviews</h1><p class="text-muted">Review student applications and give clear, constructive feedback.</p></div><form class="card p-3 mb-4"><select class="form-select" name="status" onchange="this.form.submit()"><option value="">All statuses</option><?php foreach(['submitted','under_review','shortlisted','unsuccessful','accepted'] as $x):?><option value="<?=$x?>" <?=$status===$x?'selected':''?>><?=e(ucwords(str_replace('_',' ',$x)))?></option><?php endforeach?></select></form><div class="card table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Student</th><th>Opportunity</th><th>Applied</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($apps as $a):?><tr><td><strong><?=e($a['student_name'])?></strong><div class="small text-muted"><?=e($a['education_level'])?></div></td><td><?=e($a['job_title'])?><div class="small text-muted"><?=e($a['company'])?></div></td><td><?=e($a['applied_at'])?></td><td><?=e(ucwords(str_replace('_',' ',$a['status'])))?></td><td class="text-end"><button class="btn btn-sm btn-outline-primary review-app" data-row='<?=e(json_encode($a))?>'>Review</button></td></tr><?php endforeach?></tbody></table></div><?php if(!$apps->num_rows):?><div class="card p-5 text-center text-muted">No applications found.</div><?php endif?></div>
<div class="modal fade" id="reviewModal"><div class="modal-dialog"><form class="modal-content" action="<?=url('counselor/review_application.php')?>" method="post" data-ajax><div class="modal-header"><div><h2 class="modal-title fs-5">Review application</h2><div class="small text-muted" id="reviewSummary"></div></div><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id"><a class="btn btn-outline-primary w-100 mb-3" id="resumeLink" target="_blank"><i class="bi bi-file-earmark-person"></i> View submitted resume</a><label class="form-label">Application status</label><select class="form-select mb-3" name="status" required><?php foreach(['under_review','shortlisted','unsuccessful','accepted'] as $x):?><option value="<?=$x?>"><?=e(ucwords(str_replace('_',' ',$x)))?></option><?php endforeach?></select><label class="form-label">Feedback to student</label><textarea class="form-control" name="feedback" rows="6" maxlength="3000" required placeholder="Explain the decision and give the student a useful next step."></textarea></div><div class="modal-footer"><button class="btn btn-primary">Save and notify student</button></div></form></div></div>
<script>document.querySelectorAll('.review-app').forEach(b=>b.onclick=()=>{const r=JSON.parse(b.dataset.row),m=document.getElementById('reviewModal'),f=m.querySelector('form');f.elements.id.value=r.id;f.elements.status.value=r.status==='submitted'?'under_review':r.status;f.elements.feedback.value=r.reviewer_feedback||'';document.getElementById('reviewSummary').textContent=r.student_name+' · '+r.job_title;document.getElementById('resumeLink').href=APP.base+r.resume_path;bootstrap.Modal.getOrCreateInstance(m).show()});</script><?php require dirname(__DIR__).'/includes/footer.php';?>
